import metadata from './block.json';

const { attributes: blockAttributes, supports: blockSupports } = metadata;

type SpacerAttributes = Record< string, unknown > & {
	height?: number | string;
	width?: number | string;
};

/**
 * Deprecation for the numeric `height` and `width` attributes, stored as a
 * number of pixels until the block switched to string values with units.
 *
 * Attribute-only: the markup of that version is regenerated by the parser;
 * only the sizes need migrating.
 */
const numericSizes = {
	attributes: {
		...blockAttributes,
		height: {
			type: 'number',
			default: 100,
		},
		width: {
			type: 'number',
		},
	},
	supports: blockSupports,
	isEligible( { height, width }: SpacerAttributes ) {
		return typeof height === 'number' || typeof width === 'number';
	},
	migrate( attributes: SpacerAttributes ) {
		const { height, width } = attributes;
		return {
			...attributes,
			width: width !== undefined ? `${ width }px` : undefined,
			height: height !== undefined ? `${ height }px` : undefined,
		};
	},
};

export default [ numericSizes ];
